def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Equal-colored diagonal neighbors are endpoints of a drawn segment.
    # Continue that same diagonal outward from the pair, through background,
    # stopping at another clue/object. This preserves given endpoint cells.
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    pairs.append((r, c, dr, dc, color))

    for r, c, dr, dc, color in pairs:
        for sign in (-1, 1):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                value = grid[rr][cc]
                if value not in (background, color):
                    break
                if value == background:
                    out[rr][cc] = color
                rr += sign * dr
                cc += sign * dc

    # If an isolated non-background clue lies on an already established
    # diagonal track, extend the track through the blank cells to the edge.
    # A track's color is selected by the same diagonal coordinate and nearest
    # existing line evidence; its given clue remains unchanged.
    tracks = {}
    for r in range(h):
        for c in range(w):
            if out[r][c] != background:
                continue
            colors = set()
            for rr in range(h):
                for cc in range(w):
                    if out[rr][cc] != background and (cc - rr) == (c - r):
                        colors.add(out[rr][cc])
            if len(colors) == 1:
                color = next(iter(colors))
                if grid[r][c] == background:
                    # Only complete tracks that contain existing same-color
                    # diagonal evidence, avoiding cross-color clue diagonals.
                    out[r][c] = color
    return out


