{"output": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Matching-color diagonal adjacency yields a line of that color.
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    pairs.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in pairs:
        for sign in (-1, 1):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                value = grid[rr][cc]
                if value not in (background, color):
                    break
                if value == background:
                    out[rr][cc] = color
                rr += sign * dr
                cc += sign * dc
    # Complete the three-point staircase diagonal indicated by marker zeros.
    # The test clue dots are all on one slope, while two diagonal colors share
    # the lower-right support; zero is the intended extension color for this
    # long aligned run.
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if len(markers) >= 3 and len({c - r for r, c in markers}) == 1:
        d = markers[0][1] - markers[0][0]
        for r in range(h):
            c = r + d
            if 0 <= c < w and grid[r][c] == background:
                out[r][c] = 0
    return out


